SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82dfee1f8024db2a0c1f0e39eca70ccf3e0bb732/content/books/zizhi-tongjian/vol-294/year-0958/part-05/sources/library/jiuwudaishi-118-july-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002787；EPUB电子本，纸本及异文待核", "id": "5dd3c96f-314e-5622-b644-f7d6e310f5a1"}, {"title": "宋史·巻四百八十三", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82dfee1f8024db2a0c1f0e39eca70ccf3e0bb732/content/books/zizhi-tongjian/vol-294/year-0958/part-05/sources/library/songshi-483-liucongxiao-envoys/source.txt", "note": "《宋史》巻四百八十三，段落 songshi-9c6e46fee832-p075232；EPUB电子本，纸本及异文待核", "id": "55193103-1911-5834-9de4-fcd08fd54093"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/82dfee1f8024db2a0c1f0e39eca70ccf3e0bb732/content/books/zizhi-tongjian/vol-294/year-0958/part-05/sources/library/tongjian-294-958-summer-autumn/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003489；电子底本待考，分段待核", "id": "dffe5ff1-30aa-55f8-babc-2b42241b852d"}, {"title": "资治通鉴·后周纪五", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/974130947fcdb1b84376e825c816bafd1322500d/content/books/zizhi-tongjian/vol-294/year-0958/part-03/sources/library/tongjian-294-958-peace-settlement/source.txt", "note": "《资治通鉴》后周纪五，段落 zizhi-tongjian-a63549944a71-p003488；电子底本待考，分段待核", "id": "fe823f81-8497-5757-97b7-d180f0448c0c"}, {"title": "旧五代史·卷一百十八", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/b0cccc4999dc32c7b4789dd00c3df5fb28149a70/content/books/zizhi-tongjian/vol-294/year-0958/part-04/sources/library/jiuwudaishi-118-may-958/source.txt", "note": "《旧五代史》卷一百十八，段落 jiu-wudaishi-205deb4a7860-p002785；EPUB电子本，纸本及异文待核", "id": "5a92c469-806c-5112-9fc2-bfb6fd3d0919"}, {"title": "新五代史·卷68·闽世家·王氏灭亡纪年说明", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/e77e2ab2ec0aa76443441349e3b3533923c10437/content/books/zizhi-tongjian/vol-285/year-0945/part-01/sources/library/xinwudaishi-068-fall-year/source.txt", "note": "《新五代史》卷68·闽世家·王氏灭亡纪年说明，段落 xin-wudaishi-b08f244b9241-p003415；已核卷号与传主，电子本及异文待纸本校核。", "id": "af3458df-4cef-5654-8b54-5a0ab901bec3"}]'::jsonb)
