INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "冯延鲁", "aliases": ["馮延魯"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "冯延巳的弟弟，南唐官员，曾任东都判官、礼部员外郎，与兄长同在元帅府。曾请求允许百姓卖子女；李昪去世后又参与起草包含这一规定的遗诏。生卒年尚未核。", "biography": null, "status": "draft", "id": "a589c28e-c0c5-58bf-989f-96457604ccdd"}, {"name": "钟谟", "aliases": ["鍾謨"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "会稽人，南唐吏部郎中。949年条下与李德明一起参与国政，史书称两人以辩才聪慧受到李璟宠信。与后文同名外交官的进一步经历按年代续录，生卒年尚未录入。", "biography": null, "status": "draft", "id": "ee7c4ab6-a8d3-5f0a-8b05-ede060c3934c"}, {"name": "李璟", "aliases": ["徐景通", "景通", "李景"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：李璟。", "biography": null, "status": "draft", "id": "6bf72971-88c3-5187-8f25-98cde2a9554a"}, {"name": "陈觉", "aliases": ["陳覺"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：陈觉，海陵人、参与谈议者。", "biography": null, "status": "draft", "id": "8f8c34eb-c238-596f-a688-8b8332b405a1"}, {"name": "李筠（原名李荣）", "aliases": ["李榮（控鶴指揮使）", "李荣（控鹤指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州太原人，初名荣，后来因避周世宗讳改名筠。947年任控鹤指挥使，与何福进筹划恒州起兵，先夺甲库并组织官兵与居民作战。与李昪的父亲李荣、晚唐同名李筠分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "5fa92315-29cb-56c6-9108-8f703de9861a"}, {"name": "李谦溥", "aliases": ["李謙溥"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "太原人，后周供备库副使。954年四月独自骑马说服辽州刺史投降后周。《宋史》也记同一职务与劝降行动，但把刺史姓名写作张乙，与《通鉴》张汉超不同。生卒年未载。", "biography": null, "status": "draft", "id": "ad5a349d-9360-5198-8d97-ba454f7202ae"}, {"name": "高保融", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "高从诲之子，荆南节度副使。948年十月父亲病重时，受命管理内外兵马事务；高从诲去世后，以留后身份暂掌军府。《新五代史》记他是高从诲的第三子。生卒年尚未确定。", "biography": null, "status": "draft", "id": "88e76c46-c48c-5103-9a49-99e0b54eed61"}, {"name": "孟昶", "aliases": ["孟仁赞", "孟仁贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275天成二年条所见人物：孟昶，孟子、被迎者。", "biography": null, "status": "draft", "id": "666201f7-9186-590e-8d5b-2a4a605dba69"}, {"name": "留从效", "aliases": ["留從效", "留從効"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "泉州散员指挥使，主书称桃林人，《宋史》记泉州永春人。944年参与杀黄绍颇、迎王继勋，并任都指挥使。新史写留從効，沿用同一主体。生卒年本次引文未载。", "biography": null, "status": "draft", "id": "55786b2f-a228-5281-a323-e9c521b2988f"}, {"name": "蔡仲赟", "aliases": ["蔡仲贇", "蔡仲兴", "蔡仲興"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "留从效牙将。958年着商装、革带藏绢表，间道赴周称藩。《宋史》作蔡仲贇，《新五代史》同任务使者作蔡仲兴，姓名异文保留。生卒年未载。", "biography": null, "status": "draft", "id": "9e5b4544-a181-5bc0-a87d-690f0874b766"}, {"name": "黄禹锡", "aliases": ["黃禹錫"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "留从效别驾。《宋史》记蔡仲赟送款后，又由他间道奉表，贡犀带、龙脑香。具体使日及生卒年未载。", "biography": null, "status": "draft", "id": "6f557e1f-1032-5987-8cf9-1cab86e18d45"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "李征古", "aliases": ["李徵古"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐枢密副使。《通鉴》记956年参与指控李德明卖国，后来在常州救援部署中给柴克宏朽损装备、召其回朝并拟用朱匡业替代。指控与能力评价保留来源立场，不认作李德明确实卖国。", "biography": null, "status": "draft", "id": "4166fee2-b566-55ec-8218-943eafdc5242"}, {"name": "李弘冀", "aliases": ["弘冀", "李冀"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "李璟的长子。943年七月条下被立为南昌王。姓名在《资治通鉴》作弘冀，《新五代史》同一册封作冀；沿用同一主体，不因姓名省写再建李冀。生卒年尚未核。", "biography": null, "status": "draft", "id": "e4027731-d3e9-5cd1-8c58-d504f38025da"}, {"name": "袁从范", "aliases": ["袁從范"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "南唐昭庆宫使，随徐景遂任洪州都押牙。因子遭指摘、景遂欲杀而怨望。《资治通鉴》记李弘冀密令其毒害景遂，958年八月进浆后景遂饮而卒。生卒年未载。", "biography": null, "status": "draft", "id": "56e7e836-7335-577f-9202-3a4c5c484bbd"}, {"name": "袁从范子（姓名未载）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "袁从范之子，姓名未载。有人向景遂指摘他，景遂欲杀，父亲因而怨望。指控内容及是否实际受刑未载，不记录为已处死。", "biography": null, "status": "draft", "id": "4c895c91-63b0-5435-9f0b-7d743078cdd5"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
